<?php
require_once dirname(__DIR__,2).'/src/media.php';require_method('GET');$u=current_user();$q=db()->prepare("SELECT s.*,m.mime_type,u.display_name AS owner_name,u.photo_media_id AS owner_photo_media_id,EXISTS(SELECT 1 FROM story_views v WHERE v.story_id=s.id AND v.viewer_id=?) AS viewed_by_me,(SELECT r.reaction FROM story_reactions r WHERE r.story_id=s.id AND r.user_id=?) AS my_reaction FROM stories s JOIN media m ON m.id=s.media_id JOIN users u ON u.id=s.owner_id WHERE s.deleted_at IS NULL AND s.expires_at>UTC_TIMESTAMP(6) AND (s.owner_id=? OR (s.audience='close_friends' AND EXISTS(SELECT 1 FROM close_friends c WHERE c.owner_id=s.owner_id AND c.member_id=?)) OR (s.audience='public' AND EXISTS(SELECT 1 FROM friendships f WHERE (f.user_low=s.owner_id AND f.user_high=?) OR (f.user_high=s.owner_id AND f.user_low=?)))) ORDER BY s.created_at,s.id LIMIT 200");$q->execute([$u['id'],$u['id'],$u['id'],$u['id'],$u['id'],$u['id']]);$rows=$q->fetchAll();foreach($rows as &$r)$r['extra']=$r['extra']?json_decode($r['extra'],true):null;unset($r);json_response(['stories'=>$rows,'server_time'=>gmdate('Y-m-d H:i:s')]);
